import{_ as e,W as a,X as n,a2 as i}from"./framework-6a3aa88c.js";const s={},l=i(`<h1 id="第十一课-service-名称与集群-dns" tabindex="-1"><a class="header-anchor" href="#第十一课-service-名称与集群-dns" aria-hidden="true">#</a> 第十一课：Service 名称与集群 DNS</h1><h2 id="一、本课只解决一个问题" tabindex="-1"><a class="header-anchor" href="#一、本课只解决一个问题" aria-hidden="true">#</a> 一、本课只解决一个问题</h2><p>上一课已经让商城前台 Service 找到了两个 Pod：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>Service qingyun-mall-web
       ↓
两个商城前台 Pod
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>但如果商品接口要访问商城前台，它应该把请求发到哪里？</p><p>直接使用 Pod IP 不可靠，因为 Pod 重建后 IP 可能变化。使用 Service 的 ClusterIP 虽然稳定，但人和程序都不应该到处硬编码一串 IP。</p><p>Kubernetes 给每个 Service 提供了一个可以解析的名称。本课要亲手验证：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>http://qingyun-mall-web
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>核心目标只有一句话：</p><blockquote><p>集群内的应用通常通过 Service 名称互相访问，而不是记住 Pod IP 或 ClusterIP。</p></blockquote><h2 id="二、先用生活场景理解-dns" tabindex="-1"><a class="header-anchor" href="#二、先用生活场景理解-dns" aria-hidden="true">#</a> 二、先用生活场景理解 DNS</h2><p>我们给同事打电话时，通常在通讯录里点名字，而不是背手机号：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>人能记住：张三
通讯录保存：张三 → 138...
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>DNS 做的事情很相似：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>程序使用：qingyun-mall-web
DNS 解析：qingyun-mall-web → Service ClusterIP
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>DNS 只负责把名称翻译成地址。请求被 Service 转发到哪个 Pod，仍然是 Service 和它的后端地址在负责。</p><p>完整链路是：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>集群内客户端
    ↓ 访问 http://qingyun-mall-web
集群 DNS 把名称解析成 Service ClusterIP
    ↓
Service
    ↓
某个商城前台 Pod
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="三、创建商城前台" tabindex="-1"><a class="header-anchor" href="#三、创建商城前台" aria-hidden="true">#</a> 三、创建商城前台</h2><p>进入项目目录：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">cd</span> /Users/qintianpeng/2026/code/k8s
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>创建 Deployment 和 Service：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl apply <span class="token parameter variable">-f</span> labs/09-Service与DNS/01-商城前台.yaml
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>这个 YAML 文件里用 <code>---</code> 分隔了两个 Kubernetes 对象：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>第一个对象：Deployment qingyun-mall-web
第二个对象：Service qingyun-mall-web
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>Deployment 和 Service 可以同名，因为它们的资源类型不同。</p><p>等待商城前台可用：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl rollout status deployment/qingyun-mall-web
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>查看资源：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get deployment,pod,service <span class="token parameter variable">-l</span> <span class="token assign-left variable">app</span><span class="token operator">=</span>qingyun-mall <span class="token parameter variable">-o</span> wide
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="四、先观察-service-的-clusterip" tabindex="-1"><a class="header-anchor" href="#四、先观察-service-的-clusterip" aria-hidden="true">#</a> 四、先观察 Service 的 ClusterIP</h2><p>执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get <span class="token function">service</span> qingyun-mall-web
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>结果类似：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>NAME               TYPE        CLUSTER-IP      PORT(S)
qingyun-mall-web   ClusterIP   10.96.123.45    80/TCP
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>这里的 <code>10.96.123.45</code> 只是示例。你的集群很可能是另一个地址。</p><p>我们不会记住或复制这个 IP，因为接下来要使用 Service 名称访问。</p><h2 id="五、为什么不能直接在-mac-终端测试名称" tabindex="-1"><a class="header-anchor" href="#五、为什么不能直接在-mac-终端测试名称" aria-hidden="true">#</a> 五、为什么不能直接在 Mac 终端测试名称</h2><p><code>qingyun-mall-web</code> 是 Kubernetes 集群内部的服务名称。Mac 自己使用的普通 DNS 通常不认识它。</p><p>所以不要直接在 Mac 终端执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">curl</span> http://qingyun-mall-web
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>我们要先创建一个位于集群内部的临时客户端 Pod，再从这个 Pod 发起请求。</p><p>这也更接近真实业务：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>商品接口 Pod → 商城前台 Service
订单接口 Pod → 商品接口 Service
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="六、创建集群内调试客户端" tabindex="-1"><a class="header-anchor" href="#六、创建集群内调试客户端" aria-hidden="true">#</a> 六、创建集群内调试客户端</h2><p>执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl apply <span class="token parameter variable">-f</span> labs/09-Service与DNS/02-集群内客户端.yaml
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>等待客户端 Pod 就绪：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl <span class="token function">wait</span> <span class="token parameter variable">--for</span><span class="token operator">=</span>condition<span class="token operator">=</span>Ready pod/mall-debug-client <span class="token parameter variable">--timeout</span><span class="token operator">=</span>60s
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>查看它：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get pod mall-debug-client
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>这个 Pod 使用 BusyBox 镜像，并持续休眠。它不是青云商城的正式业务组件，只是我们放进集群里的排障工具箱。</p><h2 id="七、第一次通过-service-名称访问" tabindex="-1"><a class="header-anchor" href="#七、第一次通过-service-名称访问" aria-hidden="true">#</a> 七、第一次通过 Service 名称访问</h2><p>执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl <span class="token builtin class-name">exec</span> mall-debug-client -- <span class="token function">wget</span> -qO- http://qingyun-mall-web
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>逐段解释：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>kubectl exec mall-debug-client
进入 mall-debug-client 容器执行命令

--
表示后面的内容是容器内要执行的命令

wget -qO-
发送 HTTP 请求，并把响应正文打印到终端

http://qingyun-mall-web
通过 Service 名称访问商城前台
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果看到 Nginx 欢迎页的 HTML，说明请求成功：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>mall-debug-client
       ↓ 名称解析
qingyun-mall-web Service
       ↓ 转发
商城前台 Pod
       ↓
返回 Nginx 页面
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意，我们没有使用：</p><ul><li>Pod IP；</li><li>Service ClusterIP；</li><li><code>port-forward</code>；</li><li>Mac 浏览器。</li></ul><p>这是一次真正发生在集群内部的服务间访问。</p><h2 id="八、单独观察-dns-解析" tabindex="-1"><a class="header-anchor" href="#八、单独观察-dns-解析" aria-hidden="true">#</a> 八、单独观察 DNS 解析</h2><p>刚才短名称 HTTP 请求成功，已经证明 <code>qingyun-mall-web</code> 可以在集群内使用。</p><p>现在使用 Service 的完整集群域名，只观察“名称变地址”这一步：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl <span class="token builtin class-name">exec</span> mall-debug-client -- <span class="token punctuation">\\</span>
  <span class="token function">nslookup</span> qingyun-mall-web.default.svc.cluster.local
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>结果通常包含：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>Name:      qingyun-mall-web.default.svc.cluster.local
Address:   10.96.x.x
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>这里使用完整名称，是为了让 BusyBox 的 <code>nslookup</code> 输出更干净。个别版本用短名称查询时，会在成功解析后继续尝试其他域名后缀并打印额外的 <code>NXDOMAIN</code>，容易干扰判断；这不是 Service 不可用。</p><p>这个地址应当与下面命令看到的 Service ClusterIP 一致：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get <span class="token function">service</span> qingyun-mall-web
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>因此可以得到：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>qingyun-mall-web.default.svc.cluster.local
       ↓ DNS
Service ClusterIP
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>DNS 并没有直接返回某个 Pod IP。它首先把名称解析到 Service 的稳定地址。</p><h2 id="九、亲手制造一次名称错误" tabindex="-1"><a class="header-anchor" href="#九、亲手制造一次名称错误" aria-hidden="true">#</a> 九、亲手制造一次名称错误</h2><p>故意访问一个不存在的 Service：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl <span class="token builtin class-name">exec</span> mall-debug-client -- <span class="token punctuation">\\</span>
  <span class="token function">nslookup</span> qingyun-mall-api.default.svc.cluster.local
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>这里的 <code>qingyun-mall-api</code> 没有被创建，所以会看到找不到名称一类的错误。</p><p>再执行正确名称：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl <span class="token builtin class-name">exec</span> mall-debug-client -- <span class="token punctuation">\\</span>
  <span class="token function">nslookup</span> qingyun-mall-web.default.svc.cluster.local
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>两次结果的区别说明：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>Service 名称必须准确
DNS 不会根据相似名称猜测你想访问谁
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="十、认识-service-的完整-dns-名称" tabindex="-1"><a class="header-anchor" href="#十、认识-service-的完整-dns-名称" aria-hidden="true">#</a> 十、认识 Service 的完整 DNS 名称</h2><p>我们目前的资源都位于 <code>default</code> Namespace。Service 的完整集群域名通常是：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>qingyun-mall-web.default.svc.cluster.local
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>暂时只需把它拆成四段：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>qingyun-mall-web   Service 名称
default            Namespace 名称
svc                表示 Service
cluster.local      当前集群的默认域名后缀
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在同一个 Namespace 中，通常只写短名称即可：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>qingyun-mall-web
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>也可以验证完整名称：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl <span class="token builtin class-name">exec</span> mall-debug-client -- <span class="token punctuation">\\</span>
  <span class="token function">nslookup</span> qingyun-mall-web.default.svc.cluster.local
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>然后访问：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl <span class="token builtin class-name">exec</span> mall-debug-client -- <span class="token punctuation">\\</span>
  <span class="token function">wget</span> -qO- http://qingyun-mall-web.default.svc.cluster.local
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>Namespace 后续会单独讲。本课先知道：短名称适合同一 Namespace，完整名称明确写出了 Service 所在位置。</p><h2 id="十一、dns-成功不等于-http-一定成功" tabindex="-1"><a class="header-anchor" href="#十一、dns-成功不等于-http-一定成功" aria-hidden="true">#</a> 十一、DNS 成功不等于 HTTP 一定成功</h2><p>必须分清两件事：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>DNS 成功：名称能够找到 Service 地址
HTTP 成功：请求最终到达正常工作的后端 Pod
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>可能出现这种情况：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>nslookup qingyun-mall-web.default.svc.cluster.local 成功
但是 wget http://qingyun-mall-web 失败
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>这时 DNS 大概率不是主要问题，应继续检查：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl describe <span class="token function">service</span> qingyun-mall-web
kubectl get pods <span class="token parameter variable">-l</span> <span class="token string">&#39;app=qingyun-mall,tier=frontend&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>重点确认：</p><ul><li>Service 有没有后端地址；</li><li>Pod 是否 Ready；</li><li>Service 的 <code>port</code> 和 <code>targetPort</code> 是否正确；</li><li>容器是否真的监听目标端口。</li></ul><h2 id="十二、dns-排障的最短路径" tabindex="-1"><a class="header-anchor" href="#十二、dns-排障的最短路径" aria-hidden="true">#</a> 十二、DNS 排障的最短路径</h2><p>以后在集群内通过名称访问失败，可以按顺序检查：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>1. Service 是否真的存在？
   kubectl get service

2. 名称能否解析？
   nslookup Service名称.Namespace名称.svc.cluster.local

3. Service 是否有后端？
   kubectl describe service Service名称

4. 能否发出真实 HTTP 请求？
   wget -qO- http://Service名称
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>判断方式：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>名称解析失败
→ 优先检查 Service 名、Namespace 和集群 DNS

名称解析成功，但 HTTP 失败
→ 优先检查 Service 后端、端口和应用状态
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="十三、清理实验" tabindex="-1"><a class="header-anchor" href="#十三、清理实验" aria-hidden="true">#</a> 十三、清理实验</h2><p>删除调试客户端：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl delete <span class="token parameter variable">-f</span> labs/09-Service与DNS/02-集群内客户端.yaml
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>删除商城前台：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl delete <span class="token parameter variable">-f</span> labs/09-Service与DNS/01-商城前台.yaml
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>确认清理结果：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get deployment,pod,service <span class="token parameter variable">-l</span> <span class="token assign-left variable">app</span><span class="token operator">=</span>qingyun-mall
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Pod 可能短暂处于 <code>Terminating</code>，稍后再次查看即可。</p><h2 id="十四、问题与直接回答" tabindex="-1"><a class="header-anchor" href="#十四、问题与直接回答" aria-hidden="true">#</a> 十四、问题与直接回答</h2><h3 id="为什么应用不应该直接访问-pod-ip" tabindex="-1"><a class="header-anchor" href="#为什么应用不应该直接访问-pod-ip" aria-hidden="true">#</a> 为什么应用不应该直接访问 Pod IP？</h3><p>Pod 可能因为重建、升级或迁移而更换 IP。Service 名称提供稳定入口。</p><h3 id="service-名称最终解析成什么" tabindex="-1"><a class="header-anchor" href="#service-名称最终解析成什么" aria-hidden="true">#</a> Service 名称最终解析成什么？</h3><p>对于普通 ClusterIP Service，通常解析为 Service 的 ClusterIP。</p><h3 id="为什么-mac-浏览器不能直接打开-http-qingyun-mall-web" tabindex="-1"><a class="header-anchor" href="#为什么-mac-浏览器不能直接打开-http-qingyun-mall-web" aria-hidden="true">#</a> 为什么 Mac 浏览器不能直接打开 <code>http://qingyun-mall-web</code>？</h3><p>这个名称由 Kubernetes 集群内部 DNS 管理，Mac 的普通 DNS 通常不知道它。</p><h3 id="同一个-namespace-中要写完整域名吗" tabindex="-1"><a class="header-anchor" href="#同一个-namespace-中要写完整域名吗" aria-hidden="true">#</a> 同一个 Namespace 中要写完整域名吗？</h3><p>通常不用，直接使用 Service 短名称即可。</p><h3 id="nslookup-成功-是否代表应用一定能访问成功" tabindex="-1"><a class="header-anchor" href="#nslookup-成功-是否代表应用一定能访问成功" aria-hidden="true">#</a> <code>nslookup</code> 成功，是否代表应用一定能访问成功？</h3><p>不代表。它只证明名称解析成功，还要继续验证 Service 后端、端口和应用状态。</p><h3 id="service-重建后-clusterip-发生变化怎么办" tabindex="-1"><a class="header-anchor" href="#service-重建后-clusterip-发生变化怎么办" aria-hidden="true">#</a> Service 重建后 ClusterIP 发生变化怎么办？</h3><p>只要调用方一直使用 Service 名称，DNS 会解析到当前地址，业务代码不需要跟着修改 IP。</p><h2 id="本课只记住五句话" tabindex="-1"><a class="header-anchor" href="#本课只记住五句话" aria-hidden="true">#</a> 本课只记住五句话</h2><ol><li>Pod IP 会变化，集群内应用不要依赖 Pod IP。</li><li>应用通常通过 Service 名称互相访问。</li><li>集群 DNS 把 Service 名称解析为 Service 地址。</li><li>同一 Namespace 内通常可以直接使用 Service 短名称。</li><li>DNS 成功和 HTTP 成功是两层不同的检查。</li></ol><h2 id="下一课预告" tabindex="-1"><a class="header-anchor" href="#下一课预告" aria-hidden="true">#</a> 下一课预告</h2><p>下一课学习 Namespace。我们会把青云商城的开发环境和测试环境放进不同 Namespace，观察“名称相同但互不冲突”是怎么实现的。</p>`,133),d=[l];function c(r,t){return a(),n("div",null,d)}const v=e(s,[["render",c],["__file","12-第十一课-Service名称与集群DNS.html.vue"]]);export{v as default};
